const input = $input.first().json;

// Get image keyword data
let data =
  input.imageKeywords ??
  input.image_keywords ??
  input.keywords ??
  input;

// If data is a string, parse it
if (typeof data === 'string') {
  data = data
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  try {
    data = JSON.parse(data);
  } catch (error) {
    throw new Error(
      'Image keyword data is not valid JSON: ' + error.message
    );
  }
}

// Sometimes the AI returns:
// { "imageKeywords": { ... } }
if (
  data &&
  typeof data === 'object' &&
  data.imageKeywords &&
  typeof data.imageKeywords === 'object'
) {
  data = data.imageKeywords;
}

// Sometimes it returns:
// { "keywords": { ... } }
if (
  data &&
  typeof data === 'object' &&
  data.keywords &&
  typeof data.keywords === 'object' &&
  !Array.isArray(data.keywords)
) {
  data = data.keywords;
}

// Validate
if (!data || typeof data !== 'object' || Array.isArray(data)) {
  throw new Error(
    'Image keywords must be an object containing section IDs and keyword arrays.'
  );
}

const output = [];

for (const [sectionId, keywords] of Object.entries(data)) {

  // Ignore metadata
  if (
    sectionId === 'template' ||
    sectionId === 'websiteStyle' ||
    sectionId === 'sectionCount' ||
    sectionId === 'validation'
  ) {
    continue;
  }

  let keywordList = keywords;

  // Convert string to array
  if (typeof keywordList === 'string') {
    keywordList = [keywordList];
  }

  // Skip invalid values
  if (!Array.isArray(keywordList)) {
    continue;
  }

  for (const keyword of keywordList) {

    if (
      typeof keyword !== 'string' ||
      !keyword.trim()
    ) {
      continue;
    }

    output.push({
      json: {
        section_id: sectionId,
        keyword: keyword.trim(),
        query: keyword.trim(),
        image_required: true
      }
    });
  }
}

if (output.length === 0) {
  throw new Error(
    'No valid image keywords were found.'
  );
}

return output;

// ============================================================
// IMAGE PROCESSOR
// Split image keywords → Fetch Images → Code
// Mode: Run Once for All Items
// ============================================================

// Get data from previous nodes
const splitItems = $('Split image keywords').all();
const fetchItems = $input.all();

const results = [];

// ------------------------------------------------------------
// Helper function
// ------------------------------------------------------------
function getImageUrl(photo) {
  if (!photo || !photo.src) {
    return "";
  }

  return (
    photo.src.large ||
    photo.src.medium ||
    photo.src.original ||
    photo.src.small ||
    ""
  );
}

// ------------------------------------------------------------
// Process each image request
// ------------------------------------------------------------
for (let i = 0; i < fetchItems.length; i++) {

  const splitData = splitItems[i]?.json || {};
  const fetchData = fetchItems[i]?.json || {};

  // Section
  const section =
    splitData.section ||
    fetchData.section ||
    `image-${i + 1}`;

  // Keyword
  const keyword =
    splitData.keyword ||
    fetchData.keyword ||
    "";

  // ----------------------------------------------------------
  // Check if Pexels returned an error
  // ----------------------------------------------------------
  let apiError = null;

  if (fetchData.error) {

    if (typeof fetchData.error === "string") {
      apiError = fetchData.error;
    } 
    else if (fetchData.error.message) {
      apiError = fetchData.error.message;
    } 
    else {
      apiError = JSON.stringify(fetchData.error);
    }
  }

  // ----------------------------------------------------------
  // Get Pexels photos
  // ----------------------------------------------------------
  const photos = Array.isArray(fetchData.photos)
    ? fetchData.photos
    : [];

  // First photo
  const photo = photos.length > 0
    ? photos[0]
    : null;

  // ----------------------------------------------------------
  // Get image URL
  // ----------------------------------------------------------
  const imageUrl = getImageUrl(photo);

  // ----------------------------------------------------------
  // Get alt text
  // ----------------------------------------------------------
  const altText =
    photo?.alt ||
    keyword ||
    `${section} image`;

  // ----------------------------------------------------------
  // Create image object
  // ----------------------------------------------------------
  const image = imageUrl
    ? {
        src: imageUrl,
        alt: altText
      }
    : null;

  // ----------------------------------------------------------
  // Final output
  // ----------------------------------------------------------
  results.push({
    json: {

      // Section information
      section: section,

      // Search keyword
      keyword: keyword,

      // Image object
      image: image,

      // Original Pexels photos
      photos: photos,

      // Status
      imageFound: !!imageUrl,

      // Number of photos returned
      photoCount: photos.length,

      // API error if any
      apiError: apiError,

      // Image URL separately
      imageUrl: imageUrl,

      // Alt text separately
      imageAlt: altText,

      // Processing index
      index: i
    }
  });
}

// ------------------------------------------------------------
// Return all results
// ------------------------------------------------------------
return results;

// ============================================================
// ASSEMBLE SITE CODE
// n8n Code Node
// Mode: Run Once for All Items
// ============================================================

// ------------------------------------------------------------
// 1. READ DATA FROM EXACT UPSTREAM NODES
// ------------------------------------------------------------

let planner;
let writer;
let imageItems;

try {
  planner = $('UI Planner Agent').first().json;
} catch (error) {
  throw new Error(
    'Cannot read "UI Planner Agent". Check the node name.'
  );
}

try {
  writer = $('Content Writer Agent').first().json;
} catch (error) {
  throw new Error(
    'Cannot read "Content Writer Agent". Check the node name.'
  );
}

try {
  imageItems = $('Fetch Images').all().map(item => item.json);
} catch (error) {
  imageItems = [];
}


// ------------------------------------------------------------
// 2. HELPER FUNCTIONS
// ------------------------------------------------------------

function cleanString(value, fallback = '') {
  if (value === undefined || value === null) {
    return fallback;
  }

  return String(value).trim();
}


function escapeHtml(value) {
  return cleanString(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}


function slugify(value) {
  return cleanString(value, 'my-website')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 60) || 'my-website';
}


function firstNonEmpty(...values) {
  for (const value of values) {
    if (
      value !== undefined &&
      value !== null &&
      String(value).trim() !== ''
    ) {
      return value;
    }
  }

  return '';
}


// ------------------------------------------------------------
// 3. GET BASIC WEBSITE INFORMATION
// ------------------------------------------------------------

const userRequirement =
  firstNonEmpty(
    planner.userRequirement,
    writer.userRequirement,
    planner.requirement,
    writer.requirement,
    planner.description,
    writer.description,
    ''
  );

const template =
  cleanString(
    planner.template ||
    writer.template ||
    'corporate'
  ).toLowerCase();

const businessName =
  firstNonEmpty(
    writer.businessName,
    writer.business_name,
    planner.businessName,
    planner.business_name
  ) ||
  'My Website';

const projectId =
  firstNonEmpty(
    planner.project_id,
    planner.projectId,
    writer.project_id,
    writer.projectId
  ) ||
  slugify(businessName);


// ------------------------------------------------------------
// 4. GET PLANNER SECTIONS
// ------------------------------------------------------------

let plannerSections = planner.sections || [];

if (!Array.isArray(plannerSections)) {
  plannerSections = Object.values(plannerSections);
}

if (!Array.isArray(plannerSections)) {
  plannerSections = [];
}


// ------------------------------------------------------------
// 5. GET CONTENT WRITER SECTIONS
// ------------------------------------------------------------

let writerSections =
  writer.sections ||
  writer.generatedSections ||
  {};


// ------------------------------------------------------------
// 6. NORMALIZE WRITER CONTENT
// ------------------------------------------------------------

const writerMap = {};

if (Array.isArray(writerSections)) {

  for (const section of writerSections) {

    const id =
      section.id ||
      section.section_id ||
      section.sectionId;

    if (id) {
      writerMap[String(id)] = section;
    }
  }

} else if (
  writerSections &&
  typeof writerSections === 'object'
) {

  for (const [key, value] of Object.entries(writerSections)) {

    if (
      value &&
      typeof value === 'object'
    ) {
      writerMap[String(key)] = value;
    }
  }
}


// ------------------------------------------------------------
// 7. IMAGE MAP
// ------------------------------------------------------------

const imageMap = {};


for (const image of imageItems) {

  const sectionId =
    image.section_id ||
    image.sectionId ||
    image.section ||
    image.id;

  if (!sectionId) {
    continue;
  }

  const imageUrl =
    image.image_url ||
    image.imageUrl ||
    image.url ||
    image.src?.large2x ||
    image.src?.large ||
    image.src?.original;

  if (!imageUrl) {
    continue;
  }

  if (!imageMap[sectionId]) {
    imageMap[sectionId] = [];
  }

  if (!imageMap[sectionId].includes(imageUrl)) {
    imageMap[sectionId].push(imageUrl);
  }
}


// ------------------------------------------------------------
// 8. DEFAULT 20 SECTION IDS
// ------------------------------------------------------------

const defaultSectionIds = [
  'hero',
  'intro',
  'about',
  'story',
  'services',
  'featured',
  'benefits',
  'process',
  'showcase',
  'highlights',
  'team',
  'testimonials',
  'case-studies',
  'pricing',
  'difference',
  'faq',
  'location',
  'community',
  'final-cta',
  'contact'
];


// ------------------------------------------------------------
// 9. MAKE SURE WE HAVE EXACTLY 20 SECTIONS
// ------------------------------------------------------------

let sections = [];

for (let i = 0; i < 20; i++) {

  const plannerSection =
    plannerSections[i] || {};

  const id =
    plannerSection.id ||
    plannerSection.section_id ||
    defaultSectionIds[i];

  const content =
    writerMap[id] ||
    writerMap[String(id)] ||
    {};

  const title =
    firstNonEmpty(
      content.title,
      content.heading,
      plannerSection.title,
      plannerSection.heading
    );

  const description =
    firstNonEmpty(
      content.description,
      content.subtitle,
      content.text,
      content.body,
      plannerSection.description,
      plannerSection.subtitle
    );

  const layout =
    firstNonEmpty(
      plannerSection.layout,
      content.layout,
      'default'
    );

  const cta =
    firstNonEmpty(
      content.cta,
      content.button,
      content.ctaText,
      plannerSection.cta
    );

  const images =
    imageMap[id] ||
    imageMap[String(id)] ||
    [];

  sections.push({
    id: String(id),
    title: title || `${businessName} — Section ${i + 1}`,
    description: description || '',
    layout,
    cta: cta || '',
    images,
    index: i + 1,
    content
  });
}


// ------------------------------------------------------------
// 10. TEMPLATE DESIGN SYSTEMS
// ------------------------------------------------------------

const designSystems = {

  fitness: {
    fontHeading: 'Montserrat',
    fontBody: 'Inter',
    accent: '#ff4d00',
    style: 'bold athletic',
    radius: '18px'
  },

  restaurant: {
    fontHeading: 'Playfair Display',
    fontBody: 'Inter',
    accent: '#c68b59',
    style: 'warm editorial',
    radius: '16px'
  },

  bakery: {
    fontHeading: 'Playfair Display',
    fontBody: 'Inter',
    accent: '#b86b3c',
    style: 'artisan elegant',
    radius: '18px'
  },

  ecommerce: {
    fontHeading: 'DM Sans',
    fontBody: 'Inter',
    accent: '#111111',
    style: 'minimal premium',
    radius: '14px'
  },

  saas: {
    fontHeading: 'Space Grotesk',
    fontBody: 'Inter',
    accent: '#635bff',
    style: 'modern technology',
    radius: '20px'
  },

  portfolio: {
    fontHeading: 'Space Grotesk',
    fontBody: 'Inter',
    accent: '#111111',
    style: 'creative editorial',
    radius: '20px'
  },

  education: {
    fontHeading: 'Plus Jakarta Sans',
    fontBody: 'Inter',
    accent: '#2563eb',
    style: 'clean academic',
    radius: '18px'
  },

  healthcare: {
    fontHeading: 'Plus Jakarta Sans',
    fontBody: 'Inter',
    accent: '#0f766e',
    style: 'clean trustworthy',
    radius: '18px'
  },

  'real-estate': {
    fontHeading: 'DM Sans',
    fontBody: 'Inter',
    accent: '#a16207',
    style: 'luxury property',
    radius: '16px'
  },

  travel: {
    fontHeading: 'DM Sans',
    fontBody: 'Inter',
    accent: '#0891b2',
    style: 'adventure editorial',
    radius: '20px'
  },

  technology: {
    fontHeading: 'Space Grotesk',
    fontBody: 'Inter',
    accent: '#06b6d4',
    style: 'futuristic technology',
    radius: '20px'
  },

  beauty: {
    fontHeading: 'Playfair Display',
    fontBody: 'Inter',
    accent: '#be185d',
    style: 'luxury beauty',
    radius: '20px'
  },

  agency: {
    fontHeading: 'Space Grotesk',
    fontBody: 'Inter',
    accent: '#7c3aed',
    style: 'creative agency',
    radius: '22px'
  },

  corporate: {
    fontHeading: 'DM Sans',
    fontBody: 'Inter',
    accent: '#2563eb',
    style: 'professional corporate',
    radius: '16px'
  }
};


const design =
  designSystems[template] ||
  designSystems.corporate;


// ------------------------------------------------------------
// 11. SECTION-SPECIFIC IMAGE
// ------------------------------------------------------------

function getSectionImage(section, imageIndex = 0) {

  if (
    section.images &&
    section.images.length > 0
  ) {
    return section.images[
      imageIndex % section.images.length
    ];
  }

  // External fallback only.
  // Never use local paths.
  return `https://picsum.photos/seed/${encodeURIComponent(
    businessName + '-' + section.id + '-' + imageIndex
  )}/1200/800`;
}


// ------------------------------------------------------------
// 12. GENERATE NAVIGATION
// ------------------------------------------------------------

const navItems = sections
  .slice(0, 8)
  .map(section => {

    const label =
      section.title
        .replace(/[^\w\s-]/g, '')
        .slice(0, 24);

    return `
      <a href="#${section.id}">
        ${escapeHtml(label)}
      </a>
    `;
  })
  .join('');


// ------------------------------------------------------------
// 13. RENDER DIFFERENT SECTION TYPES
// ------------------------------------------------------------

function renderSection(section) {

  const id = section.id;
  const title = escapeHtml(section.title);
  const description = escapeHtml(section.description);
  const image = getSectionImage(section);

  const cta =
    section.cta
      ? `
        <a class="btn btn-primary"
           href="#contact">
           ${escapeHtml(section.cta)}
        </a>
      `
      : '';


  // HERO
  if (id === 'hero') {

    return `
      <section
        id="${id}"
        class="section hero-section"
      >

        <div class="hero-overlay"></div>

        <img
          class="hero-image"
          src="${escapeHtml(image)}"
          alt="${escapeHtml(section.title)}"
          loading="eager"
        >

        <div class="hero-content container">

          <span class="eyebrow">
            ${escapeHtml(template.toUpperCase())}
          </span>

          <h1>${title}</h1>

          <p>${description}</p>

          <div class="hero-actions">
            ${cta}

            <a
              class="btn btn-secondary"
              href="#intro"
            >
              Explore More
            </a>
          </div>

        </div>

      </section>
    `;
  }


  // INTRO
  if (id === 'intro') {

    return `
      <section
        id="${id}"
        class="section intro-section"
      >

        <div class="container narrow">

          <span class="section-number">
            02
          </span>

          <h2>${title}</h2>

          <p class="large-text">
            ${description}
          </p>

          ${cta}

        </div>

      </section>
    `;
  }


  // ABOUT
  if (id === 'about' || id === 'story') {

    return `
      <section
        id="${id}"
        class="section split-section"
      >

        <div class="container split-grid">

          <div class="split-image">
            <img
              src="${escapeHtml(image)}"
              alt="${escapeHtml(section.title)}"
              loading="lazy"
            >
          </div>

          <div class="split-content">

            <span class="section-number">
              ${String(section.index).padStart(2, '0')}
            </span>

            <h2>${title}</h2>

            <p>${description}</p>

            ${cta}

          </div>

        </div>

      </section>
    `;
  }


  // SERVICES
  if (
    id === 'services' ||
    id === 'programs' ||
    id === 'featured'
  ) {

    const cards = [
      0,
      1,
      2
    ].map((index) => {

      const cardImage =
        getSectionImage(section, index);

      const cardTitle =
        section.content?.items?.[index]?.title ||
        `${section.title} ${index + 1}`;

      const cardDescription =
        section.content?.items?.[index]?.description ||
        section.description;

      return `
        <article class="service-card">

          <div class="card-image">
            <img
              src="${escapeHtml(cardImage)}"
              alt="${escapeHtml(cardTitle)}"
              loading="lazy"
            >
          </div>

          <div class="card-body">

            <span class="card-index">
              0${index + 1}
            </span>

            <h3>
              ${escapeHtml(cardTitle)}
            </h3>

            <p>
              ${escapeHtml(cardDescription)}
            </p>

          </div>

        </article>
      `;
    }).join('');

    return `
      <section
        id="${id}"
        class="section"
      >

        <div class="container">

          <div class="section-heading">

            <span class="section-number">
              ${String(section.index).padStart(2, '0')}
            </span>

            <h2>${title}</h2>

            <p>${description}</p>

          </div>

          <div class="service-grid">
            ${cards}
          </div>

        </div>

      </section>
    `;
  }


  // BENEFITS
  if (
    id === 'benefits' ||
    id === 'difference'
  ) {

    const benefits = [
      'Designed around your goals',
      'Simple and effective experience',
      'Flexible approach for different needs',
      'Focused on meaningful results'
    ];

    return `
      <section
        id="${id}"
        class="section benefits-section"
      >

        <div class="container">

          <div class="section-heading">
            <span class="section-number">
              ${String(section.index).padStart(2, '0')}
            </span>

            <h2>${title}</h2>

            <p>${description}</p>
          </div>

          <div class="benefits-grid">

            ${benefits.map((item, index) => `
              <div class="benefit-item">

                <span>
                  ${String(index + 1).padStart(2, '0')}
                </span>

                <h3>
                  ${escapeHtml(item)}
                </h3>

                <p>
                  ${escapeHtml(description)}
                </p>

              </div>
            `).join('')}

          </div>

        </div>

      </section>
    `;
  }


  // PROCESS
  if (id === 'process') {

    const steps = [
      'Discover',
      'Plan',
      'Build',
      'Improve'
    ];

    return `
      <section
        id="${id}"
        class="section process-section"
      >

        <div class="container">

          <div class="section-heading">
            <span class="section-number">
              ${String(section.index).padStart(2, '0')}
            </span>

            <h2>${title}</h2>

            <p>${description}</p>
          </div>

          <div class="process-grid">

            ${steps.map((step, index) => `
              <div class="process-step">

                <div class="process-number">
                  ${String(index + 1).padStart(2, '0')}
                </div>

                <h3>
                  ${escapeHtml(step)}
                </h3>

                <p>
                  ${escapeHtml(description)}
                </p>

              </div>
            `).join('')}

          </div>

        </div>

      </section>
    `;
  }


  // SHOWCASE / CASE STUDIES
  if (
    id === 'showcase' ||
    id === 'case-studies'
  ) {

    return `
      <section
        id="${id}"
        class="section showcase-section"
      >

        <div class="container">

          <div class="section-heading">
            <span class="section-number">
              ${String(section.index).padStart(2, '0')}
            </span>

            <h2>${title}</h2>

            <p>${description}</p>
          </div>

          <div class="showcase-grid">

            <div class="showcase-large">
              <img
                src="${escapeHtml(
                  getSectionImage(section, 0)
                )}"
                alt="${escapeHtml(title)}"
                loading="lazy"
              >
            </div>

            <div class="showcase-small">
              <img
                src="${escapeHtml(
                  getSectionImage(section, 1)
                )}"
                alt="${escapeHtml(title)}"
                loading="lazy"
              >
            </div>

          </div>

        </div>

      </section>
    `;
  }


  // TEAM
  if (id === 'team') {

    return `
      <section
        id="${id}"
        class="section"
      >

        <div class="container">

          <div class="section-heading">
            <span class="section-number">
              ${String(section.index).padStart(2, '0')}
            </span>

            <h2>${title}</h2>

            <p>${description}</p>
          </div>

          <div class="team-grid">

            ${[0, 1, 2].map((index) => {

              const teamImage =
                getSectionImage(section, index);

              return `
                <article class="team-card">

                  <img
                    src="${escapeHtml(teamImage)}"
                    alt="Team member"
                    loading="lazy"
                  >

                  <div class="team-info">

                    <h3>
                      ${escapeHtml(
                        section.content?.items?.[index]?.title ||
                        `Team Member ${index + 1}`
                      )}
                    </h3>

                    <p>
                      ${escapeHtml(
                        section.content?.items?.[index]?.description ||
                        description
                      )}
                    </p>

                  </div>

                </article>
              `;

            }).join('')}

          </div>

        </div>

      </section>
    `;
  }


  // TESTIMONIALS
  if (id === 'testimonials') {

    return `
      <section
        id="${id}"
        class="section testimonial-section"
      >

        <div class="container testimonial-inner">

          <span class="quote-mark">
            “
          </span>

          <h2>${title}</h2>

          <p class="testimonial-text">
            ${description}
          </p>

          <div class="testimonial-line"></div>

          <span class="testimonial-label">
            Customer Experience
          </span>

        </div>

      </section>
    `;
  }


  // PRICING
  if (id === 'pricing') {

    const plans = [
      'Starter',
      'Professional',
      'Premium'
    ];

    return `
      <section
        id="${id}"
        class="section"
      >

        <div class="container">

          <div class="section-heading">

            <span class="section-number">
              ${String(section.index).padStart(2, '0')}
            </span>

            <h2>${title}</h2>

            <p>${description}</p>

          </div>

          <div class="pricing-grid">

            ${plans.map((plan, index) => `

              <article
                class="pricing-card ${
                  index === 1
                    ? 'featured-plan'
                    : ''
                }"
              >

                <span class="plan-number">
                  0${index + 1}
                </span>

                <h3>
                  ${plan}
                </h3>

                <p>
                  ${escapeHtml(description)}
                </p>

                <ul>

                  <li>Flexible options</li>
                  <li>Quality experience</li>
                  <li>Designed for your needs</li>

                </ul>

                <a
                  href="#contact"
                  class="btn btn-primary"
                >
                  Get Started
                </a>

              </article>

            `).join('')}

          </div>

        </div>

      </section>
    `;
  }


  // FAQ
  if (id === 'faq') {

    const questions = [
      'How does it work?',
      'Who is this suitable for?',
      'How can I get started?',
      'How can I contact you?'
    ];

    return `
      <section
        id="${id}"
        class="section faq-section"
      >

        <div class="container faq-grid">

          <div>

            <span class="section-number">
              ${String(section.index).padStart(2, '0')}
            </span>

            <h2>${title}</h2>

            <p>${description}</p>

          </div>

          <div class="faq-list">

            ${questions.map((question, index) => `
              <details>

                <summary>
                  ${escapeHtml(question)}
                  <span>+</span>
                </summary>

                <p>
                  ${escapeHtml(description)}
                </p>

              </details>
            `).join('')}

          </div>

        </div>

      </section>
    `;
  }


  // LOCATION
  if (id === 'location') {

    return `
      <section
        id="${id}"
        class="section location-section"
      >

        <div class="container location-grid">

          <div>

            <span class="section-number">
              ${String(section.index).padStart(2, '0')}
            </span>

            <h2>${title}</h2>

            <p>${description}</p>

            ${cta}

          </div>

          <div class="location-image">

            <img
              src="${escapeHtml(image)}"
              alt="${escapeHtml(title)}"
              loading="lazy"
            >

          </div>

        </div>

      </section>
    `;
  }


  // COMMUNITY
  if (id === 'community') {

    return `
      <section
        id="${id}"
        class="section community-section"
      >

        <div class="container community-inner">

          <span class="section-number">
            ${String(section.index).padStart(2, '0')}
          </span>

          <h2>${title}</h2>

          <p>${description}</p>

          ${cta}

        </div>

      </section>
    `;
  }


  // FINAL CTA
  if (id === 'final-cta') {

    return `
      <section
        id="${id}"
        class="section final-cta"
      >

        <div class="container">

          <span class="section-number">
            ${String(section.index).padStart(2, '0')}
          </span>

          <h2>${title}</h2>

          <p>${description}</p>

          ${
            cta ||
            `
              <a
                href="#contact"
                class="btn btn-primary"
              >
                Get Started
              </a>
            `
          }

        </div>

      </section>
    `;
  }


  // CONTACT
  if (id === 'contact') {

    const email =
      writer.contactInfo?.email ||
      writer.contact?.email ||
      '';

    const phone =
      writer.contactInfo?.phone ||
      writer.contact?.phone ||
      '';

    return `
      <section
        id="contact"
        class="section contact-section"
      >

        <div class="container contact-grid">

          <div class="contact-content">

            <span class="section-number">
              ${String(section.index).padStart(2, '0')}
            </span>

            <h2>${title}</h2>

            <p>${description}</p>

            ${
              email
                ? `
                  <p>
                    <strong>Email:</strong>
                    ${escapeHtml(email)}
                  </p>
                `
                : ''
            }

            ${
              phone
                ? `
                  <p>
                    <strong>Phone:</strong>
                    ${escapeHtml(phone)}
                  </p>
                `
                : ''
            }

          </div>

          <form
            class="contact-form"
            id="contactForm"
          >

            <input
              type="text"
              name="name"
              placeholder="Your name"
              required
            >

            <input
              type="email"
              name="email"
              placeholder="Your email"
              required
            >

            <textarea
              name="message"
              rows="6"
              placeholder="Tell us how we can help"
              required
            ></textarea>

            <button
              type="submit"
              class="btn btn-primary"
            >
              Send Message
            </button>

          </form>

        </div>

      </section>
    `;
  }


  // DEFAULT SECTION
  return `
    <section
      id="${id}"
      class="section default-section"
    >

      <div class="container default-grid">

        <div>

          <span class="section-number">
            ${String(section.index).padStart(2, '0')}
          </span>

          <h2>${title}</h2>

          <p>${description}</p>

          ${cta}

        </div>

        <div class="default-image">

          <img
            src="${escapeHtml(image)}"
            alt="${escapeHtml(title)}"
            loading="lazy"
          >

        </div>

      </div>

    </section>
  `;
}


