// ============================================================
// PREPARE WEBSITE FILES FOR GITHUB
// ============================================================

// Get GitHub repository response from the previous node
const gitPost = $input.first().json;


// Get website data from Assemble Site Code
const websiteData = $('Assemble Site Code').first().json;


// ------------------------------------------------------------
// Validate files
// ------------------------------------------------------------

if (!websiteData.files) {
  throw new Error(
    'No "files" array found in Assemble Site Code output.'
  );
}

if (!Array.isArray(websiteData.files)) {
  throw new Error(
    '"files" must be an array.'
  );
}

if (websiteData.files.length === 0) {
  throw new Error(
    'The files array is empty.'
  );
}


// ------------------------------------------------------------
// Project information
// ------------------------------------------------------------

const projectId =
  websiteData.project_id ||
  gitPost.name ||
  `website-${Date.now()}`;

const businessName =
  websiteData.business_name ||
  websiteData.businessName ||
  'Website';


// ------------------------------------------------------------
// Create ONE n8n item for EACH file
// ------------------------------------------------------------

return websiteData.files.map((file, index) => {

  const filename =
    file.filename ||
    file.name ||
    `file-${index + 1}.txt`;

  const content =
    file.content ?? '';

  return {
    json: {

      // Project
      project_id: projectId,

      business_name: businessName,

      // GitHub repository
      repository_owner:
        gitPost.owner?.login ||
        'dhanussh430',

      repository_name:
        gitPost.name ||
        projectId,

      repository_full_name:
        gitPost.full_name ||
        '',

      repository_url:
        gitPost.html_url ||
        '',

      // Current file
      filename: filename,

      content: String(content),

      // Base64 version if needed later
      content_base64:
        Buffer
          .from(String(content), 'utf8')
          .toString('base64'),

      // Useful debugging information
      file_index: index,

      file_count:
        websiteData.files.length

    }
  };

});

let payload;

try {
  // Works when triggered via the Webhook (Flowise, HTTP calls, etc.)
  payload = $('Webhook').item.json.body;
} catch (e) {
  // Falls back to this when triggered via "When Executed by Another Workflow"
  payload = $('When Executed by Another Workflow').item.json;
}

return [{
  json: {
    project_id: payload.project_id,
    business_name: payload.business_name,
    files: payload.files
  }
}];

// ==========================================
// FINAL CHAT RESPONSE
// Convert multiple deployment items into
// ONE clean response for the chat
// ==========================================

const items = $input.all();

if (items.length === 0) {
  return [
    {
      json: {
        status: "error",
        message: "❌ No deployment result was received."
      }
    }
  ];
}

// Take the first item because the deployment
// currently produces multiple items (one per file)
const item = items[0].json;

// Safely get values
const businessName =
  item.business_name ||
  item.businessName ||
  "Your Website";

const projectId =
  item.project_id ||
  "N/A";

const liveUrl =
  item.live_url ||
  item.url ||
  "";

const repoUrl =
  item.repo_url ||
  item.repository_url ||
  "";

// ------------------------------------------
// Build final chat message
// ------------------------------------------

let message = `🎉 Website created successfully!

🏪 Business: ${businessName}

🆔 Project ID:
${projectId}
`;

// Add live website URL if available
if (liveUrl) {
  message += `
🌐 Live Website:
${liveUrl}
`;
}

// Add GitHub URL if available
if (repoUrl) {
  message += `
📦 GitHub Repository:
${repoUrl}
`;
}

message += `
✅ Website deployment completed successfully!`;

// ------------------------------------------
// Return ONE item
// ------------------------------------------

return [
  {
    json: {
      status: "success",
      business_name: businessName,
      project_id: projectId,
      live_url: liveUrl,
      repo_url: repoUrl,
      message: message
    }
  }
];

